package com.sweatsenhancements.config;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * One feature: its id, the category it belongs to, and its name.
 * Immutable, generated by Features.java.
 */
public class Feature {

    public final String id;
    public final String category;
    public final String name;

    public Feature(String id, String category, String name) {
        this.id = id;
        this.category = category;
        this.name = name;
    }

    /** True when this feature actually does something in the current build. */
    public boolean isLive() {
        return Implemented.IDS.contains(id);
    }

    @Override
    public String toString() {
        return id + " " + name;
    }
}
